"""Small conservative XML minifier used by the CLI implementation."""
import re


_TOKEN = re.compile(r"<!--.*?-->|<!\[CDATA\[.*?\]\]>|<\?.*?\?>|<![^>]*>|<[^>]*>|[^<]+", re.S)


def minify(source: str, keep_whitespace: bool = False) -> str:
    out = []
    comment_space = False
    had_text = False
    for match in _TOKEN.finditer(source):
        token = match.group(0)
        if token.startswith("<!--"):
            comment_space = bool(out and not out[-1].startswith("<") and source[:match.start()].endswith((" ", "\n", "\r", "\t")))
            continue
        if token.startswith("<?"):
            out.append(token)
            continue
        if token.startswith("<![CDATA["):
            # CDATA content becomes ordinary character data when the wrapper
            # is removed, so escape characters that would otherwise be markup.
            token = token[9:-3].replace("&", "&amp;").replace("<", "&lt;")
            if not token:
                continue
        if token.startswith("<"):
            if token.startswith("<!") and not token.startswith("<![CDATA["):
                out.append(token)
                continue
            if token.endswith("/>"):
                token = re.sub(r"\s+/>$", "/>" , token)
            if token.startswith("</") and out and out[-1].startswith("<") and not out[-1].startswith("<!"):
                # Empty element pair: <x></x> -> <x/>
                opening = out[-1]
                name = re.match(r"<\s*([^\s/>]+)", opening)
                closing = re.match(r"</\s*([^\s>]+)", token)
                if name and closing and name.group(1) == closing.group(1):
                    out[-1] = opening[:-1].rstrip() + "/>"
                    continue
            out.append(token)
        else:
            had_leading_space = bool(token[:1].isspace())
            keep_leading = had_text
            if keep_whitespace:
                token = re.sub(r"\s+", lambda m: "\n" if "\n" in m.group(0) or "\r" in m.group(0) else " ", token)
            else:
                token = re.sub(r"\s+", lambda m: "\n" if "\n" in m.group(0) or "\r" in m.group(0) else " ", token)
                token = token.lstrip() if keep_leading else token.lstrip()
                token = token.rstrip()
                if keep_leading and had_leading_space:
                    token = " " + token
            if token:
                had_text = True
                if comment_space and had_leading_space and out and not out[-1].startswith("<"):
                    if keep_whitespace:
                        out[-1] = out[-1].rstrip(" \n")
                        token = token.lstrip(" \n")
                    out.append(" ")
                # Whitespace between tags is insignificant in XML default mode.
                if token == " " and out and out[-1].startswith("<"):
                    continue
                out.append(token)
            comment_space = False
    return "".join(out)

