def canonical_type(value):
    """Resolve a CLI type name, extension, or MIME type to a MIME type."""
    value = (value or '').strip()
    if '/' not in value:
        key = value.removeprefix('.')
        if key in EXTENSIONS:
            return EXTENSIONS[key]
    return value

def minify(data, media_type, options=None):
    """Minify decoded text according to a type or MIME type string."""
    options = options or {}
    def opt(key, default=None):
        return options.get(key, options.get(key.replace('-', '_'), default))
    mime = canonical_type(media_type).split(';', 1)[0].strip()
    if mime == 'text/css':
        return minify_css(data, int(opt('css-precision', 0) or 0), int(opt('css-version', 0) or 0))
    if mime in ('application/javascript', 'text/javascript', 'application/x-javascript', 'text/x-javascript', 'text/ecmascript', 'application/ecmascript', 'application/x-ecmascript', 'text/x-ecmascript'):
        return minify_js(data, options)
    if mime.endswith('/json') or mime.endswith('+json') or mime == 'application/manifest+json':
        return minify_json(data, bool(opt('json-keep-numbers')), int(opt('json-precision', 0) or 0))
    if mime == 'image/svg+xml':
        return minify_svg(data, bool(opt('svg-keep-comments')), int(opt('svg-precision', 0) or 0), opt('svg-keep-namespaces'))
    if mime.endswith('/xml') or mime.endswith('+xml'):
